# pega todo el contenido, luego Ctrl+D
#!/usr/bin/env bash
# ============================================================
#  SHIFT logo installer
#  Adds the ShiftLogo component, the app icons, and wires the
#  sidebar to use it. Backs up page.js before touching it.
#
#  Usage, from the repo root:   bash shift-logo.sh
# ============================================================
set -euo pipefail

[ -d app ] && [ -d components ] || { echo "Run this from the repo root, the one that holds app/ and components/."; exit 1; }
mkdir -p public/logo

write_text() {
  cat > "$1"
  echo "    write   $1"
}
write_b64() {
  base64 -d > "$1"
  echo "    write   $1  (binary)"
}

echo "==> writing logo files"
write_text components/ShiftLogo.js << '__SHIFT_EOF__'
const BLUE = '#3B6FB6';
const AMBER = '#D08A2C';
const EYE = '#F4F7F2';

const LEFT = 'M31 8C20 8 12 16 12 26L8 33l4 2v4c0 4 3 6 6 7l5 3v8h8z';
const RIGHT = 'M33 8c11 0 19 8 19 18l4 7-4 2v4c0 4-3 6-6 7l-5 3v8h-8z';

const WORDMARK_FONT =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Helvetica, Arial, sans-serif';

function Faces({ left = BLUE, right = AMBER, eye = EYE, showEyes = true }) {
  return (
    <>
      <path d={LEFT} fill={left} />
      <path d={RIGHT} fill={right} />
      {showEyes && (
        <>
          <circle cx="17" cy="27" r="2.4" fill={eye} />
          <circle cx="47" cy="27" r="2.4" fill={eye} />
        </>
      )}
    </>
  );
}

/**
 * SHIFT logo.
 *
 * variant:
 *   'lockup'  mark + wordmark, horizontal (default)
 *   'stacked' mark above wordmark, centered
 *   'mark'    Janus mark only, in brand colors
 *   'mono'    Janus mark only, single color (inherits currentColor)
 *   'icon'    rounded square app icon, dark background
 *
 * size = rendered height in px. Width scales automatically.
 * The wordmark uses currentColor, so it follows your text color in light and dark mode.
 */
export default function ShiftLogo({
  variant = 'lockup',
  size = 32,
  className = '',
  title = 'SHIFT',
  ...rest
}) {
  const common = {
    className,
    role: 'img',
    'aria-label': title,
    xmlns: 'http://www.w3.org/2000/svg',
    ...rest,
  };

  if (variant === 'mark' || variant === 'mono') {
    const mono = variant === 'mono';
    return (
      <svg viewBox="0 0 64 64" width={size} height={size} {...common}>
        {mono ? (
          <>
            <path d={LEFT} fill="currentColor" />
            <path d={RIGHT} fill="currentColor" opacity="0.55" />
          </>
        ) : (
          <Faces />
        )}
      </svg>
    );
  }

  if (variant === 'icon') {
    return (
      <svg viewBox="0 0 64 64" width={size} height={size} {...common}>
        <rect width="64" height="64" rx="14" fill="#132235" />
        <Faces left="#5B93DA" right="#E5A03F" eye="#132235" />
      </svg>
    );
  }

  if (variant === 'stacked') {
    return (
      <svg
        viewBox="0 0 160 108"
        width={(size * 160) / 108}
        height={size}
        {...common}
      >
        <g transform="translate(48 0)">
          <Faces />
        </g>
        <text
          x="80"
          y="98"
          textAnchor="middle"
          fontFamily={WORDMARK_FONT}
          fontSize="28"
          fontWeight="500"
          letterSpacing="5"
          fill="currentColor"
        >
          SHIFT
        </text>
      </svg>
    );
  }

  return (
    <svg viewBox="0 0 232 64" width={(size * 232) / 64} height={size} {...common}>
      <Faces />
      <text
        x="82"
        y="44"
        fontFamily={WORDMARK_FONT}
        fontSize="34"
        fontWeight="500"
        letterSpacing="6"
        fill="currentColor"
      >
        SHIFT
      </text>
    </svg>
  );
}

__SHIFT_EOF__
write_text app/icon.svg << '__SHIFT_EOF__'
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64" role="img" aria-label="SHIFT">
  <rect width="64" height="64" rx="14" fill="#132235"/>
  <path d="M31 8C20 8 12 16 12 26L8 33l4 2v4c0 4 3 6 6 7l5 3v8h8z" fill="#5B93DA"/>
  <path d="M33 8c11 0 19 8 19 18l4 7-4 2v4c0 4-3 6-6 7l-5 3v8h-8z" fill="#E5A03F"/>
  <circle cx="17" cy="27" r="2.4" fill="#132235"/>
  <circle cx="47" cy="27" r="2.4" fill="#132235"/>
</svg>

__SHIFT_EOF__
write_text public/logo/shift-lockup.svg << '__SHIFT_EOF__'
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 232 64" width="232" height="64" role="img" aria-label="SHIFT">
  <path d="M31 8C20 8 12 16 12 26L8 33l4 2v4c0 4 3 6 6 7l5 3v8h8z" fill="#3B6FB6"/>
  <path d="M33 8c11 0 19 8 19 18l4 7-4 2v4c0 4-3 6-6 7l-5 3v8h-8z" fill="#D08A2C"/>
  <circle cx="17" cy="27" r="2.4" fill="#F4F7F2"/>
  <circle cx="47" cy="27" r="2.4" fill="#F4F7F2"/>
  <text x="82" y="44" font-family="Inter, ui-sans-serif, system-ui, -apple-system, Segoe UI, Helvetica, Arial, sans-serif" font-size="34" font-weight="500" letter-spacing="6" fill="currentColor">SHIFT</text>
</svg>

__SHIFT_EOF__
write_text public/logo/shift-lockup-stacked.svg << '__SHIFT_EOF__'
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 108" width="160" height="108" role="img" aria-label="SHIFT">
  <g transform="translate(48 0)">
    <path d="M31 8C20 8 12 16 12 26L8 33l4 2v4c0 4 3 6 6 7l5 3v8h8z" fill="#3B6FB6"/>
    <path d="M33 8c11 0 19 8 19 18l4 7-4 2v4c0 4-3 6-6 7l-5 3v8h-8z" fill="#D08A2C"/>
    <circle cx="17" cy="27" r="2.4" fill="#F4F7F2"/>
    <circle cx="47" cy="27" r="2.4" fill="#F4F7F2"/>
  </g>
  <text x="80" y="98" text-anchor="middle" font-family="Inter, ui-sans-serif, system-ui, -apple-system, Segoe UI, Helvetica, Arial, sans-serif" font-size="28" font-weight="500" letter-spacing="5" fill="currentColor">SHIFT</text>
</svg>

__SHIFT_EOF__
write_text public/logo/shift-mark.svg << '__SHIFT_EOF__'
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64" role="img" aria-label="SHIFT">
  <path d="M31 8C20 8 12 16 12 26L8 33l4 2v4c0 4 3 6 6 7l5 3v8h8z" fill="#3B6FB6"/>
  <path d="M33 8c11 0 19 8 19 18l4 7-4 2v4c0 4-3 6-6 7l-5 3v8h-8z" fill="#D08A2C"/>
  <circle cx="17" cy="27" r="2.4" fill="#F4F7F2"/>
  <circle cx="47" cy="27" r="2.4" fill="#F4F7F2"/>
</svg>

__SHIFT_EOF__
write_text public/logo/shift-mark-mono.svg << '__SHIFT_EOF__'
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64" role="img" aria-label="SHIFT">
  <path d="M31 8C20 8 12 16 12 26L8 33l4 2v4c0 4 3 6 6 7l5 3v8h8z" fill="currentColor"/>
  <path d="M33 8c11 0 19 8 19 18l4 7-4 2v4c0 4-3 6-6 7l-5 3v8h-8z" fill="currentColor" opacity="0.55"/>
</svg>

__SHIFT_EOF__
write_text public/logo/favicon.svg << '__SHIFT_EOF__'
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64" role="img" aria-label="SHIFT">
  <rect width="64" height="64" rx="14" fill="#132235"/>
  <path d="M31 8C20 8 12 16 12 26L8 33l4 2v4c0 4 3 6 6 7l5 3v8h8z" fill="#5B93DA"/>
  <path d="M33 8c11 0 19 8 19 18l4 7-4 2v4c0 4-3 6-6 7l-5 3v8h-8z" fill="#E5A03F"/>
  <circle cx="17" cy="27" r="2.4" fill="#132235"/>
  <circle cx="47" cy="27" r="2.4" fill="#132235"/>
</svg>

__SHIFT_EOF__
write_b64 app/apple-icon.png << '__SHIFT_EOF__'

__SHIFT_EOF__
write_b64 public/icon-192.png << '__SHIFT_EOF__'

__SHIFT_EOF__
write_b64 public/icon-512.png << '__SHIFT_EOF__'

__SHIFT_EOF__
echo
echo "==> wiring the sidebar to use the logo"
[ -f app/page.js.bak ] || cp app/page.js app/page.js.bak
echo "    backup  app/page.js.bak (if not already present)"
python3 << '__SHIFT_EOF__'
import re
p = "app/page.js"
s = open(p).read()

if "ShiftLogo" not in s:
    s = s.replace(
        'import Icon from "../components/Icon";',
        'import Icon from "../components/Icon";\nimport ShiftLogo from "../components/ShiftLogo";',
        1,
    )
    s = s.replace(
        '<div className="logo-mark">S</div>',
        '<ShiftLogo variant="mark" size={30} />',
        1,
    )
    open(p, "w").write(s)
    print("    patched app/page.js")
else:
    print("    app/page.js already wired, skipping")
__SHIFT_EOF__

echo
echo "==> sanity check"
for f in components/ShiftLogo.js app/icon.svg app/apple-icon.png public/icon-192.png public/icon-512.png; do
  [ -s "$f" ] && echo "    ok      $f" || echo "    MISSING $f"
done

echo
echo "Done. Restart the dev server:  npm run dev"
echo "The browser tab icon may need a hard refresh (Ctrl+Shift+R) to pick up the new favicon."
